type mStoreMockRecord struct {
	optional           bool
	mock               *StoreMock
	defaultExpectation *StoreMockRecordExpectation
	expectations       []*StoreMockRecordExpectation

	callArgs []*StoreMockRecordParams
	mutex    sync.RWMutex

	expectedInvocations       uint64
	expectedInvocationsOrigin string
}

// StoreMockRecordExpectation specifies expectation struct of the Store.Record
type StoreMockRecordExpectation struct {
	mock               *StoreMock
	params             *StoreMockRecordParams
	paramPtrs          *StoreMockRecordParamPtrs
	expectationOrigins StoreMockRecordExpectationOrigins
	results            *StoreMockRecordResults
	returnOrigin       string
	Counter            uint64
}

// StoreMockRecordParams contains parameters of the Store.Record
type StoreMockRecordParams struct {
	ctx context.Context
	e   domain.Entry
}

// StoreMockRecordParamPtrs contains pointers to parameters of the Store.Record
type StoreMockRecordParamPtrs struct {
	ctx *context.Context
	e   *domain.Entry
}

// StoreMockRecordResults contains results of the Store.Record
type StoreMockRecordResults struct {
	i1  int64
	err error
}

// StoreMockRecordOrigins contains origins of expectations of the Store.Record
type StoreMockRecordExpectationOrigins struct {
	origin    string
	originCtx string
	originE   string
}

// Marks this method to be optional. The default behavior of any method with Return() is '1 or more', meaning
// the test will fail minimock's automatic final call check if the mocked method was not called at least once.
// Optional() makes method check to work in '0 or more' mode.
// It is NOT RECOMMENDED to use this option unless you really need it, as default behaviour helps to
// catch the problems when the expected method call is totally skipped during test run.
func (mmRecord *mStoreMockRecord) Optional() *mStoreMockRecord {
	mmRecord.optional = true
	return mmRecord
}

// Expect sets up expected params for Store.Record
func (mmRecord *mStoreMockRecord) Expect(ctx context.Context, e domain.Entry) *mStoreMockRecord {
	if mmRecord.mock.funcRecord != nil {
		mmRecord.mock.t.Fatalf("StoreMock.Record mock is already set by Set")
	}

	if mmRecord.defaultExpectation == nil {
		mmRecord.defaultExpectation = &StoreMockRecordExpectation{}
	}

	if mmRecord.defaultExpectation.paramPtrs != nil {
		mmRecord.mock.t.Fatalf("StoreMock.Record mock is already set by ExpectParams functions")
	}

	mmRecord.defaultExpectation.params = &StoreMockRecordParams{ctx, e}
	mmRecord.defaultExpectation.expectationOrigins.origin = minimock.CallerInfo(1)
	for _, e := range mmRecord.expectations {
		if minimock.Equal(e.params, mmRecord.defaultExpectation.params) {
			mmRecord.mock.t.Fatalf("Expectation set by When has same params: %#v", *mmRecord.defaultExpectation.params)
		}
	}

	return mmRecord
}

